launch_cmds:
set -e
if [ -s "$HOME/.nvm/nvm.sh" ]; then . "$HOME/.nvm/nvm.sh" && nvm use 20; fi
env -u APP_ID -u APP_SECRET -u USER_ACCESS_TOKEN -u LARK_TOKEN_MODE node dist/cli.js mcp --credential-mode passthrough --mode streamable --host 0.0.0.0 --port ${PORT:-8000} --domain ${LARK_DOMAIN:-https://open.feishu.cn} --tools ${LARK_TOOLS:-preset.default} --language ${LARK_LANGUAGE:-zh}
